const API_URL =
  process.env.NEXT_PUBLIC_API_URL || "http://127.0.0.1:5000";

export type DocumentItem = {
  id: string;
  title: string;
  source_type?: string;
  created_at?: string;
};

async function request<T>(
  path: string,
  options: RequestInit = {},
  token?: string
): Promise<T> {
  const response = await fetch(`${API_URL}${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      ...(token ? { Authorization: `Bearer ${token}` } : {}),
      ...options.headers
    }
  });

  const data = await response.json().catch(() => ({}));

  if (!response.ok) {
    throw new Error(
      data.error || data.message || `Request failed (${response.status})`
    );
  }

  return data as T;
}

export async function login(email: string, password: string) {
  return request<{ access_token: string }>("/api/auth/login", {
    method: "POST",
    body: JSON.stringify({ email, password })
  });
}

export async function getDocuments(token: string) {
  const result = await request<
    DocumentItem[] | { documents?: DocumentItem[] }
  >("/api/knowledge/documents", {}, token);

  return Array.isArray(result) ? result : result.documents || [];
}

export async function addDocument(
  token: string,
  title: string,
  content: string
) {
  return request("/api/knowledge/documents", {
    method: "POST",
    body: JSON.stringify({
      title,
      content,
      source_type: "paste"
    })
  }, token);
}
